/** The tasks this app's extensions contribute: request and response types from each extension's schema. */
export interface Tasks {
  /** makegood-units 1.5.0: task id https://extensions.adcontextprotocol.org/makegood-units#request_makegood */
  request_makegood: { request: makegood_units.MakegoodRequest; response: makegood_units.MakegoodResponse };
}

/** The buyer client: core tasks with this app's types, and one method per contributed task. */
export interface Client extends BoundClient<Forms> {
  /** request_makegood (makegood-units 1.5.0), under the transport name the seller declares. The buyer asks the seller to issue a make-good unit under an accepted rule for a missed deliverable. The seller answers accepted, with the zero-cost package that carries the unit, or rejected, with a reason. */
  requestMakegood(request: makegood_units.MakegoodRequest): Promise<makegood_units.MakegoodResponse>;
}

/** The seller server: one typed handler per core task and per contributed task. */
export type Server = BoundServer<Forms, Tasks, Attribute>;

// The contributed task: request and response types come from the extension's schema.
server.handle('request_makegood', (req) => {
  const buy = buys.get(req.media_buy_id);
  if (!buy) throw new SellerRejection('MEDIA_BUY_NOT_FOUND', req.media_buy_id);
  const rule = buy.accepted_proposal.commercial_terms.makegood_units?.rules.find((r) => r.rule_id === req.rule_id);
  const ledger = buy.makegood_units; // this extension's readback ledger, a plain attribute
  const issued = ledger?.issued ?? [];
  if (!rule || buy.packages[rule.purchase_index].package_id !== req.package_id) {
    return { status: 'completed', outcome: 'rejected', rule_id: req.rule_id, rejection: { code: 'RULE_NOT_ACCEPTED', message: `no accepted rule ${req.rule_id} for ${req.package_id}` } };
  }
  if (issued.filter((u) => u.rule_id === rule.rule_id).length >= rule.max_units) {
    return { status: 'completed', outcome: 'rejected', rule_id: rule.rule_id, rejection: { code: 'CAP_EXCEEDED', message: `max_units ${rule.max_units} used` } };
  }
  …
  if (ledger) ledger.issued.push(unit);
  else buy.makegood_units = { issued: [unit] };
  return { status: 'completed', outcome: 'accepted', rule_id: rule.rule_id, makegood_id: unit.makegood_id, package_id: unit.package_id, revision: unit.revision, change_id: unit.change_id };

// request_makegood is a typed method of this app's client: one method per task its extensions contribute.
const request = { media_buy_id, rule_id: 'mg_video_2', package_id: 'pkg_video_2', reason: 'deliverable_missed' } as const;
const answer = await client.requestMakegood({ ...request, idempotency_key: 'makegood-0001-aaaaaaa' });
if (answer.outcome === 'accepted') log(`request_makegood (${client.lastTaskCall?.name}): accepted, unit ${answer.makegood_id} in package ${answer.package_id}, revision ${answer.revision}`);
await new Promise((r) => setTimeout(r, 10));
const again = await client.requestMakegood({ ...request, idempotency_key: 'makegood-0002-aaaaaaa' });
if (again.outcome === 'rejected') log(`a second request under the same rule: ${again.rejection.code}: ${again.rejection.message}`);

